export function preparePlayerLooks(project){const p=authoring(project).presentation;if(!p.playerLookVariableId){const v=addVariable(project,'Player appearance',{bits:8,kind:'appearance'});p.playerLookVariableId=v.id;}return p.playerLookVariableId;}
