function branch(bytes,at,to){const d=to-at-4;if(d%2||d< -0x400000||d>=0x400000)throw Error('A Thumb branch is out of range.');const v=new DataView(bytes.buffer,bytes.byteOffset,bytes.byteLength);v.setUint16(at,0xf000|((d>>12)&2047),true);v.setUint16(at+2,0xf800|((d>>1)&2047),true);}
