 const rows=plan.options.map(o=>{if(!Array.isArray(o.values)||o.values.length<2||o.values.length>4)throw Error(o.name+': use 2–4 option values.');return {name:o.name,values:o.values,variable:readAuthoring(project).variables.find(v=>v.id===o.variableId)};});if(plan.looks.length)rows.push({name:'Player appearance',values:lookRows.map(l=>l.name),variable:plan.variable});
 if(rows.length){if(reader.u16(p.optionInput)!==0xb510||reader.u16(p.optionExit)!==0x482b||reader.u32(p.optionNames+24)<BASE)throw Error('The native Options hooks failed verification.');const original=reader.bytes.slice(p.optionInput,p.optionEnd);config.inputOriginal=alloc(original,'Preserved native Options input')|1;config.exitContinue=p.optionContinue;config.optionInit=p.optionInit;const data=new Uint8Array(rows.length*16),v=new DataView(data.buffer);for(const [i,r]of rows.entries()){const bitSlots=slots(r.variable);v.setUint32(i*16,string(r.name.slice(0,34)),true);v.setUint32(i*16+4,alloc(words(r.values.map(value=>string(value.slice(0,34)))),'Option choices'),true);v.setUint32(i*16+8,alloc(words(bitSlots,2),'Option save bits'),true);v.setUint16(i*16+12,r.values.length,true);v.setUint16(i*16+14,bitSlots.length,true);}config.optionRows=alloc(data,'Native project Options entries');config.optionCount=rows.length;}
